INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_ETHIOPIAN','Ethiopian Christian (Aksumite to Solomonic)',330,1500)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BUDGE_KEBRA_NAGAST','primary text','E. A. Wallis Budge (trans.), The Queen of Sheba and Her Only Son Menyelek (Kebra Nagast) (London, 1922)','Kebra Nagast cycle: Makeda, Menelik I, the Ark/Tabot, the Solomonic dynasty'),
 ('SRC_MUNRO_HAY_AKSUM','secondary scholarship','Stuart Munro-Hay, Aksum: An African Civilisation of Late Antiquity','Aksumite Christianization, Frumentius, the Nine Saints, Ethiopian church history (REUSED existing source)')
INSERT INTO _e VALUES
 ('ENT_ETH_SAINTS','Saints of the Ethiopian Tewahedo Church','Collective','saintly collective','Ethiopian Christian','sanctity; evangelization; monasticism; kingship','B','Hub collective for the canonized saints, sages, and Solomonic-cycle figures of Ethiopian Tewahedo Christianity; analytic grouping per Munro-Hay.'),
 ('ENT_ETH_NINE_SAINTS','The Nine Saints','Collective','missionary collective','Ethiopian Christian','evangelization; monasticism; translation of scripture','B','Group of nine (largely Syriac/Roman) missionary monks who, c. late 5th-early 6th c., spread monasticism and consolidated Christianity in Aksumite Ethiopia; attested in Ethiopian synaxaria and discussed by Munro-Hay.'),
 ('ENT_ETH_FRUMENTIUS','Frumentius (Abba Selama)','Bishop/saint','apostle of Ethiopia','Ethiopian Christian','apostolate; episcopacy; conversion of Aksum','B','First bishop of Aksum, called Abba Selama ''Revealer of Light''; converted King Ezana and the Aksumite court in the 4th c.; consecrated by Athanasius of Alexandria. Attested by Rufinus and Athanasius; treated by Munro-Hay.'),
 ('ENT_ETH_AREGAWI','Abba Aregawi (Za-Mikael)','Abbot/saint','monastic saint','Ethiopian Christian','monasticism; asceticism','B','Best-known of the Nine Saints; traditional founder of Debre Damo monastery. Attested in Ethiopian hagiography; discussed by Munro-Hay.'),
 ('ENT_ETH_YARED','Saint Yared','Hymnographer/saint','hymnographer saint','Ethiopian Christian','sacred music; liturgy; hymnody','B','6th-c. deacon credited with inventing Ethiopian sacred chant (zema) and its notation; central to Tewahedo liturgy. Attested in Ethiopian tradition; noted by Munro-Hay.'),
 ('ENT_ETH_TEKLE_HAYMANOT','Tekle Haymanot','Abbot/saint','monastic saint','Ethiopian Christian','monasticism; asceticism; evangelization','B','13th-c. monastic saint, founder of Debre Libanos and a key figure in the Solomonic restoration; among the most venerated Ethiopian saints. Attested in his Gadl (hagiography).'),
 ('ENT_ETH_GEBRE_MENFES_KIDUS','Gebre Menfes Kidus (Abbo)','Ascetic/saint','ascetic saint','Ethiopian Christian','asceticism; eremitism','C','Popular Ethiopian hermit-saint (''Servant of the Holy Spirit''), associated with Mount Ziquala; legendary ascetic figure of Ethiopian hagiography.'),
 ('ENT_ETH_LALIBELA','Gebre Mesqel Lalibela','King/saint','king-saint','Ethiopian Christian','kingship; church-building; sanctity','B','Zagwe king (c. 1181-1221) credited with the rock-hewn churches of Lalibela (''New Jerusalem''); canonized king-saint. Attested historically and in his Gadl; discussed by Munro-Hay.'),
 ('ENT_ETH_MAKEDA','Makeda, Queen of Sheba','Queen','Kebra Nagast figure','Ethiopian Christian','kingship; dynastic origin; wisdom-tradition','B','Ethiopian name for the Queen of Sheba; in the Kebra Nagast she visits Solomon and bears Menelik I, founding the Solomonic line. Reception/expansion of the biblical Queen of Sheba (1 Kings 10). Homonym/parallel of the biblical Sheba figure.'),
 ('ENT_ETH_MENELIK','Menelik I','King','Kebra Nagast figure','Ethiopian Christian','kingship; dynastic founding; the Ark tradition','B','Legendary son of Solomon and Makeda; founder of the Ethiopian Solomonic dynasty who, in the Kebra Nagast, brings the Ark of the Covenant from Jerusalem to Aksum.'),
 ('ENT_ETH_TABOT','The Tabot (Ark of the Covenant tradition)','Sacred object','sacred object/tradition','Ethiopian Christian','cultus; covenant; liturgy','B','The Ethiopian Ark tradition: the Tabot (altar-tablet) replicates the Ark of the Covenant believed, per the Kebra Nagast, to reside at Aksum; central cultic object of every Tewahedo church.');
