INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_ETH_SAINTS','PER_ETHIOPIAN','Hub collective for the canonized saints, sages, and Solomonic-cycle figures of Ethiopian Tewahedo Christianity; analytic grouping per Munro-Hay.'),
 ('ENT_ETH_NINE_SAINTS','PER_ETHIOPIAN','Group of nine (largely Syriac/Roman) missionary monks who, c. late 5th-early 6th c., spread monasticism and consolidated Christianity in Aksumite Ethiopia; attested in Ethiopian synaxaria and discussed by Munro-Hay.'),
 ('ENT_ETH_FRUMENTIUS','PER_ETHIOPIAN','First bishop of Aksum, called Abba Selama ''Revealer of Light''; converted King Ezana and the Aksumite court in the 4th c.; consecrated by Athanasius of Alexandria. Attested by Rufinus and Athanasius; treated by Munro-Hay.'),
 ('ENT_ETH_AREGAWI','PER_ETHIOPIAN','Best-known of the Nine Saints; traditional founder of Debre Damo monastery. Attested in Ethiopian hagiography; discussed by Munro-Hay.'),
 ('ENT_ETH_YARED','PER_ETHIOPIAN','6th-c. deacon credited with inventing Ethiopian sacred chant (zema) and its notation; central to Tewahedo liturgy. Attested in Ethiopian tradition; noted by Munro-Hay.'),
 ('ENT_ETH_TEKLE_HAYMANOT','PER_ETHIOPIAN','13th-c. monastic saint, founder of Debre Libanos and a key figure in the Solomonic restoration; among the most venerated Ethiopian saints. Attested in his Gadl (hagiography).'),
 ('ENT_ETH_GEBRE_MENFES_KIDUS','PER_ETHIOPIAN','Popular Ethiopian hermit-saint (''Servant of the Holy Spirit''), associated with Mount Ziquala; legendary ascetic figure of Ethiopian hagiography.'),
 ('ENT_ETH_LALIBELA','PER_ETHIOPIAN','Zagwe king (c. 1181-1221) credited with the rock-hewn churches of Lalibela (''New Jerusalem''); canonized king-saint. Attested historically and in his Gadl; discussed by Munro-Hay.'),
 ('ENT_ETH_MAKEDA','PER_ETHIOPIAN','Ethiopian name for the Queen of Sheba; in the Kebra Nagast she visits Solomon and bears Menelik I, founding the Solomonic line. Reception/expansion of the biblical Queen of Sheba (1 Kings 10). Homonym/parallel of the biblical Sheba figure.'),
 ('ENT_ETH_MENELIK','PER_ETHIOPIAN','Legendary son of Solomon and Makeda; founder of the Ethiopian Solomonic dynasty who, in the Kebra Nagast, brings the Ark of the Covenant from Jerusalem to Aksum.'),
 ('ENT_ETH_TABOT','PER_ETHIOPIAN','The Ethiopian Ark tradition: the Tabot (altar-tablet) replicates the Ark of the Covenant believed, per the Kebra Nagast, to reside at Aksum; central cultic object of every Tewahedo church.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_ETH_FRUMENTIUS','member_of','ENT_ETH_SAINTS','high','Frumentius is the founding apostle-bishop in the Ethiopian saintly canon.'),
 ('ENT_ETH_NINE_SAINTS','member_of','ENT_ETH_SAINTS','high','The Nine Saints are a core evangelizing group within the Ethiopian saintly tradition.'),
 ('ENT_ETH_AREGAWI','member_of','ENT_ETH_NINE_SAINTS','high','Abba Aregawi is the best-known of the Nine Saints.'),
 ('ENT_ETH_AREGAWI','member_of','ENT_ETH_SAINTS','high','Aregawi is a canonical Ethiopian monastic saint.'),
 ('ENT_ETH_YARED','member_of','ENT_ETH_SAINTS','high','Yared, inventor of Ethiopian chant, is a major Tewahedo saint.'),
 ('ENT_ETH_TEKLE_HAYMANOT','member_of','ENT_ETH_SAINTS','high','Tekle Haymanot is among the most venerated Ethiopian monastic saints.'),
 ('ENT_ETH_GEBRE_MENFES_KIDUS','member_of','ENT_ETH_SAINTS','high','Gebre Menfes Kidus is a popular Ethiopian ascetic saint.'),
 ('ENT_ETH_LALIBELA','member_of','ENT_ETH_SAINTS','high','King Lalibela is a canonized king-saint of the Ethiopian church.'),
 ('ENT_ETH_MAKEDA','member_of','ENT_ETH_SAINTS','medium','Makeda is the foundational figure of the Kebra Nagast cycle revered in Ethiopian Christian tradition.'),
 ('ENT_ETH_MENELIK','member_of','ENT_ETH_SAINTS','medium','Menelik I, founder of the Solomonic dynasty, is venerated in the Kebra Nagast cycle.'),
 ('ENT_ETH_FRUMENTIUS','taught_by','ENT_SAINT_ANTHONY_ABBOT','low','Ethiopian monasticism traces its ideals to Egyptian Antonian/Pachomian asceticism mediated through Alexandria, the see that consecrated Frumentius; lineage-of-influence, not personal pupillage. ENT_SAINT_ANTHONY_ABBOT verified to exist.'),
 ('ENT_ETH_NINE_SAINTS','taught_by','ENT_SAINT_ANTHONY_ABBOT','low','The Nine Saints introduced Egyptian-style monasticism deriving from the Antonian/Pachomian tradition into Ethiopia. ENT_SAINT_ANTHONY_ABBOT verified to exist.'),
 ('ENT_ETH_MENELIK','child_of','ENT_ETH_MAKEDA','high','In the Kebra Nagast, Menelik I is the son of Queen Makeda.'),
 ('ENT_ETH_MENELIK','child_of','ENT_ISR_SOLOMON','high','The Kebra Nagast makes Menelik I the son of Solomon by Makeda, founding the Solomonic dynasty. ENT_ISR_SOLOMON verified to exist.'),
 ('ENT_ETH_MAKEDA','associated_with','ENT_ISR_SOLOMON','high','In the Kebra Nagast Makeda (the Ethiopian Queen of Sheba) visits Solomon and bears his son Menelik I; the figure is a reception/expansion of the biblical Queen of Sheba''s visit (1 Kings 10). Retargeted from reception_of to associated_with because Makeda is a reception of the biblical Queen of Sheba (no such DB entity exists), not of Solomon. ENT_ISR_SOLOMON verified to exist.'),
 ('ENT_ETH_MENELIK','associated_with','ENT_ETH_TABOT','high','Menelik I is said in the Kebra Nagast to have brought the Ark (Tabot) from Jerusalem to Aksum.'),
 ('ENT_ETH_TABOT','associated_with','ENT_ETH_SAINTS','medium','The Tabot/Ark tradition is the central cultic object of the Ethiopian Tewahedo Church carried by its saintly lineage.'),
 ('ENT_ETH_YARED','patron_of','ENT_ETH_SAINTS','low','Yared is patron of Ethiopian sacred music, the liturgical tradition the saintly church carries forward.');
